const PERIOD_MS = 15 * 60 * 1000

function uuidv4 () {
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
        const r = Math.random() * 16 | 0
        const v = c === 'x' ? r : (r & 0x3 | 0x8)
        return v.toString(16)
    })
}

function nextPeriodStart () {
    const now = Date.now()
    let next = Math.ceil(now / PERIOD_MS) * PERIOD_MS
    if (next <= now) next += PERIOD_MS
    return new Date(next).toISOString().replace(/\.\d{3}Z$/, 'Z')
}

const limits = msg.payload || {}
const lower = limits.lower_limit
const upper = limits.upper_limit

if (typeof lower !== 'number' || typeof upper !== 'number') {
    node.error('msg.payload must be {"lower_limit": <number>, "upper_limit": <number>}', msg)
    return null
}

const resourceManagerId = flow.get('resourceManagerId')
const cemBaseUrl = flow.get('cemBaseUrl')
const powerConstraintsId = flow.get('pebcPowerConstraintsId')

if (!resourceManagerId || !cemBaseUrl || !powerConstraintsId) {
    node.error('Missing flow.resourceManagerId / flow.cemBaseUrl / flow.pebcPowerConstraintsId - run the "Configure (once)" inject after filling in the Config node', msg)
    return null
}

msg.url = `${cemBaseUrl.replace(/\/$/, '')}/resource_managers/${resourceManagerId}/flex_instructions`

msg.payload = {
    id: uuidv4(),
    message_id: uuidv4(),
    message_type: 'PEBC.Instruction',
    execution_time: nextPeriodStart(),
    power_envelopes: [{
        id: uuidv4(),
        commodity_quantity: 'ELECTRIC.POWER.3_PHASE_SYMMETRIC',
        power_envelope_elements: [{
            duration: PERIOD_MS,
            lower_limit: lower,
            upper_limit: upper
        }]
    }],
    abnormal_condition: false,
    power_constraints_id: powerConstraintsId
}

return msg
